  return { batch: B2, skillId: 'M4.NUM.070', K: 'K3', T: 'T5', family: 'parity_product',
    prompt: `Tích của ${n} số tự nhiên liên tiếp bất kì luôn là số chẵn hay số lẻ? Giải thích vì sao.`, answer: choice('số chẵn', ['số chẵn', 'số lẻ']),
    hints: ['Thử vài trường hợp: 1 × 2, 2 × 3 × 4, 5 × 6 × 7...', 'Trong các số tự nhiên liên tiếp, cứ cách một số lại có một số chẵn.', `Trong ${n} số liên tiếp có ít nhất một số chẵn không?`, 'Ví dụ dễ hơn: 7 × 8 có 8 chẵn; 9 × 10 × 11 có 10 chẵn.', 'Một thừa số chẵn thì tích có chia hết cho 2 không?', `Trong ${n} số tự nhiên liên tiếp luôn có ít nhất một số chẵn. Tích có một thừa số chẵn nên chia hết cho 2, vậy tích là số chẵn.`],
    solution: `Trong ${n} số tự nhiên liên tiếp luôn có ít nhất một số chẵn. Tích có một thừa số chẵn thì chia hết cho 2, nên tích là số chẵn.` };
